import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { ROLES } from '../utils/roles';
import { useNavigate } from 'react-router-dom';
import ErrorBox from '../components/ErrorBox';

const HomePage = () => {
  const [doctorEmail, setDoctorEmail] = useState('');
  const [doctorPassword, setDoctorPassword] = useState('');
  const [patientEmail, setPatientEmail] = useState('');
  const [patientPassword, setPatientPassword] = useState('');
  const [doctorError, setDoctorError] = useState('');
  const [patientError, setPatientError] = useState('');
  const [doctorLoading, setDoctorLoading] = useState(false);
  const [patientLoading, setPatientLoading] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleDoctorLogin = async (e) => {
    e.preventDefault();
    setDoctorError('');
    setDoctorLoading(true);

    const result = await login(doctorEmail, doctorPassword);

    if (result.success) {
      if (result.user.role === ROLES.DOCTOR) {
        navigate('/doctor/dashboard');
      } else {
        setDoctorError('Invalid credentials for doctor');
      }
    } else {
      setDoctorError(result.message || 'Login failed');
    }
    setDoctorLoading(false);
  };

  const handlePatientLogin = async (e) => {
    e.preventDefault();
    setPatientError('');
    setPatientLoading(true);

    const result = await login(patientEmail, patientPassword);

    if (result.success) {
      if (result.user.role === ROLES.PATIENT) {
        navigate('/patient/dashboard');
      } else {
        setPatientError('Invalid credentials for patient');
      }
    } else {
      setPatientError(result.message || 'Login failed');
    }
    setPatientLoading(false);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100">
      <div className="container mx-auto px-4 py-12">
        {/* Header */}
        <div className="text-center mb-12">
          <h1 className="text-5xl font-bold text-blue-600 mb-4">MedConnect+</h1>
          <p className="text-xl text-gray-700">Hospital Management System</p>
        </div>

        {/* Login Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 max-w-6xl mx-auto">
          {/* Doctor Login Card */}
          <div className="bg-white rounded-lg shadow-xl p-8">
            <div className="text-center mb-6">
              <div className="inline-block bg-blue-100 rounded-full p-4 mb-4">
                <svg className="w-12 h-12 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
                </svg>
              </div>
              <h2 className="text-2xl font-bold text-gray-800 mb-2">Doctor Login</h2>
              <p className="text-gray-600">Access your doctor dashboard</p>
            </div>

            {doctorError && <ErrorBox message={doctorError} onClose={() => setDoctorError('')} />}

            <form onSubmit={handleDoctorLogin} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Email
                </label>
                <input
                  type="email"
                  value={doctorEmail}
                  onChange={(e) => setDoctorEmail(e.target.value)}
                  className="w-full px-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  placeholder="doctor@medconnect.com"
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Password
                </label>
                <input
                  type="password"
                  value={doctorPassword}
                  onChange={(e) => setDoctorPassword(e.target.value)}
                  className="w-full px-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  placeholder="Enter your password"
                  required
                />
              </div>

              <button
                type="submit"
                disabled={doctorLoading}
                className="w-full bg-blue-600 text-white py-3 px-4 rounded-md hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 disabled:opacity-50 font-semibold transition"
              >
                {doctorLoading ? 'Logging in...' : 'Login as Doctor'}
              </button>
            </form>

            <div className="mt-4 text-center">
              <p className="text-sm text-gray-600">
                Don't have an account?{' '}
                <Link to="/register/doctor" className="text-blue-600 hover:text-blue-800 font-semibold">
                  Register as Doctor
                </Link>
              </p>
            </div>
          </div>

          {/* Patient Login Card */}
          <div className="bg-white rounded-lg shadow-xl p-8">
            <div className="text-center mb-6">
              <div className="inline-block bg-green-100 rounded-full p-4 mb-4">
                <svg className="w-12 h-12 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" />
                </svg>
              </div>
              <h2 className="text-2xl font-bold text-gray-800 mb-2">Patient Login</h2>
              <p className="text-gray-600">Access your patient portal</p>
            </div>

            {patientError && <ErrorBox message={patientError} onClose={() => setPatientError('')} />}

            <form onSubmit={handlePatientLogin} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Email
                </label>
                <input
                  type="email"
                  value={patientEmail}
                  onChange={(e) => setPatientEmail(e.target.value)}
                  className="w-full px-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-green-500"
                  placeholder="patient@medconnect.com"
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Password
                </label>
                <input
                  type="password"
                  value={patientPassword}
                  onChange={(e) => setPatientPassword(e.target.value)}
                  className="w-full px-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-green-500"
                  placeholder="Enter your password"
                  required
                />
              </div>

              <button
                type="submit"
                disabled={patientLoading}
                className="w-full bg-green-600 text-white py-3 px-4 rounded-md hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-green-500 disabled:opacity-50 font-semibold transition"
              >
                {patientLoading ? 'Logging in...' : 'Login as Patient'}
              </button>
            </form>

            <div className="mt-4 text-center">
              <p className="text-sm text-gray-600">
                Don't have an account?{' '}
                <Link to="/register" className="text-green-600 hover:text-green-800 font-semibold">
                  Register as Patient
                </Link>
              </p>
            </div>
          </div>
        </div>

        {/* Features Section */}
        <div className="mt-16 text-center">
          <h3 className="text-2xl font-bold text-gray-800 mb-8">Features</h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-4xl mx-auto">
            <div className="bg-white rounded-lg p-6 shadow-md">
              <div className="text-4xl mb-4">👨‍⚕️</div>
              <h4 className="font-semibold text-lg mb-2">For Doctors</h4>
              <p className="text-gray-600 text-sm">View patients, manage appointments, and create prescriptions</p>
            </div>
            <div className="bg-white rounded-lg p-6 shadow-md">
              <div className="text-4xl mb-4">👤</div>
              <h4 className="font-semibold text-lg mb-2">For Patients</h4>
              <p className="text-gray-600 text-sm">Book appointments, view doctors, and access prescriptions</p>
            </div>
            <div className="bg-white rounded-lg p-6 shadow-md">
              <div className="text-4xl mb-4">📋</div>
              <h4 className="font-semibold text-lg mb-2">Digital Prescriptions</h4>
              <p className="text-gray-600 text-sm">QR code enabled prescriptions sent via email</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default HomePage;
